package com.stayhaven.web;
import com.stayhaven.domain.*; import com.stayhaven.repo.*; import com.stayhaven.service.BookingService;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.security.core.Authentication;
import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class HotelApiController {
 private final RoomRepository rooms; private final RoomUnitRepository units; private final BookingRepository bookings; private final BookingService bookingService; private final AccountRepository accounts;
 public HotelApiController(RoomRepository r,RoomUnitRepository u,BookingRepository b,BookingService s,AccountRepository a){rooms=r;units=u;bookings=b;bookingService=s;accounts=a;}
 @GetMapping("/rooms/{id}") public ResponseEntity<?> room(@PathVariable Long id){return rooms.findWithHotelById(id).<ResponseEntity<?>>map(r->ResponseEntity.ok(Map.of("id",r.getId(),"hotel",r.getHotel().getName(),"type",r.getType(),"description",r.getDescription(),"pricePerNight",r.getPricePerNight(),"capacity",r.getCapacity(),"units",units.findByRoomId(id).stream().map(u->Map.of("id",u.getId(),"roomNumber",u.getRoomNumber(),"floor",u.getFloor(),"bedType",u.getBedType(),"status",u.getStatus())).toList()))).orElseGet(()->ResponseEntity.notFound().build());}
 @GetMapping("/availability") public Map<String,Object> availability(@RequestParam Long roomId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut){Room r=rooms.findById(roomId).orElseThrow();if(!checkIn.isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata")))||!checkOut.isAfter(checkIn))throw new IllegalArgumentException("Invalid stay dates");long count=units.findByRoomId(roomId).stream().filter(u->!Set.of("MAINTENANCE","CLEANING").contains(u.getStatus())&&bookings.countOverlappingUnit(u.getId(),checkIn,checkOut)==0).count();return Map.of("roomId",roomId,"checkIn",checkIn,"checkOut",checkOut,"availableUnits",count,"available",count>0,"pricePerNight",r.getPricePerNight());}
 @PostMapping("/bookings") public ResponseEntity<?> create(@Valid @RequestBody BookingRequest request,Authentication auth){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Booking b=bookingService.create(a,request.roomId(),request.checkIn(),request.checkOut(),request.guests(),a.getName(),a.getEmail());return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("id",b.getId(),"reference",b.getReference(),"status",b.getStatus(),"paymentStatus",b.getPaymentStatus(),"checkIn",b.getCheckIn(),"checkOut",b.getCheckOut(),"total",b.getTotalPrice()));}
 @PostMapping("/admin/bookings/{id}/status") public Map<String,Object> updateStatus(@PathVariable Long id,@RequestParam String status){Booking b=bookingService.updateStatus(id,status);return Map.of("reference",b.getReference(),"status",b.getStatus());}
 public record BookingRequest(@NotNull Long roomId,@NotNull LocalDate checkIn,@NotNull LocalDate checkOut,@Min(1) int guests){}
}
